#' Anytime-Valid Monitoring
#'
#' Continuous monitoring with anytime-valid inference: Gaussian-mixture 
#' e-values (the mixture SPRT for a known SD, the safe t-test for an unknown 
#' SD), always-valid p-values and confidence sequences for a mean or a 
#' difference in means, valid at every sample size and under optional 
#' stopping. The design gives the sample size for a target power, exact for a 
#' known SD and simulated otherwise.
#' @param data .
#' @param dep .
#' @param group .
#' @param samples .
#' @param sdKnown .
#' @param sigma .
#' @param mu0 .
#' @param alpha .
#' @param delta .
#' @param power .
#' @param mixing .
#' @param g .
#' @param nMax .
#' @param nsim .
#' @param seed .
#' @param every .
#' @param curvePlot .
#' @param ePlot .
#' @param csPlot .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$monitor} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$curvePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$ePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$csPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
anytime <- function(
    data,
    dep = NULL,
    group = NULL,
    samples = "two",
    sdKnown = FALSE,
    sigma = 1,
    mu0 = 0,
    alpha = 0.05,
    delta = 0.5,
    power = 0.8,
    mixing = "delta",
    g = 0.25,
    nMax = 0,
    nsim = 1000,
    seed = 1,
    every = 0,
    curvePlot = TRUE,
    ePlot = TRUE,
    csPlot = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("anytime requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- anytimeOptions$new(
        dep = dep,
        group = group,
        samples = samples,
        sdKnown = sdKnown,
        sigma = sigma,
        mu0 = mu0,
        alpha = alpha,
        delta = delta,
        power = power,
        mixing = mixing,
        g = g,
        nMax = nMax,
        nsim = nsim,
        seed = seed,
        every = every,
        curvePlot = curvePlot,
        ePlot = ePlot,
        csPlot = csPlot)

    analysis <- anytimeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

